import {generatedMap} from './generated-materials.mjs';
import {makeFlameMaterial} from './homestead-details.mjs';
import * as T from './vendor/three.module.js';
import {blocked,route} from './logic.mjs';
import {HAY_FIELD as F,POND_CAMP as C} from './alp-life.mjs';
export function createAlpLifeWorld(scene,height,colliders,interactive,animated,materials){
 let lifeState=null;const root=new T.Group();scene.add(root);root.userData.kind='alp-life';const mat=c=>new T.MeshStandardMaterial({color:c,roughness:.9}),black=mat('#262b29'),white=mat('#e7e2d3'),tan=mat('#b68c65'),grassMat=mat('#859c4c'),hayMat=mat('#b7a66a'),wood=materials.wood;
 const fur=generatedMap('animal-materials',3),woolMap=generatedMap('animal-materials',1),wool=new T.MeshStandardMaterial({color:woolMap?'#ffffff':'#e7e2d3',map:woolMap,roughness:1});if(fur){white.map=fur;black.map=fur;}const hayMap=generatedMap('hay');if(hayMap){hayMat.map=hayMap;hayMat.color.set('#ffffff');}
 function mesh(geo,m,p=root){const o=new T.Mesh(geo,m);o.castShadow=o.receiveShadow=true;p.add(o);return o;}
 const sphere=new T.SphereGeometry(1,18,12);function ball(p,m,x,y,z,a,b,c){const o=mesh(sphere,m,p);o.position.set(x,y,z);o.scale.set(a,b,c);return o;}
 function rod(p,a,b,r,m){const u=new T.Vector3(...a),v=new T.Vector3(...b),d=v.clone().sub(u),o=mesh(new T.CylinderGeometry(r*.65,r,d.length(),9),m,p);o.position.copy(u.add(v).multiplyScalar(.5));o.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),d.normalize());return o;}
 const meadowMap=generatedMap('hay-meadow-20261018'),count=1800,clock={value:0};
 const meadowMaterial=new T.MeshStandardMaterial({color:meadowMap?'#ffffff':'#88a250',map:meadowMap,side:T.DoubleSide,roughness:1,alphaTest:.4,alphaToCoverage:true});
 meadowMaterial.onBeforeCompile=shader=>{shader.uniforms.hayTime=clock;shader.vertexShader='uniform float hayTime;\n'+shader.vertexShader;shader.vertexShader=shader.vertexShader.replace('#include <begin_vertex>','#include <begin_vertex>\n#ifdef USE_INSTANCING\ntransformed.x+=sin(hayTime*1.2+instanceMatrix[3][0]+instanceMatrix[3][2])*.035*uv.y*uv.y;\n#endif');};
 const grass=new T.InstancedMesh(new T.PlaneGeometry(meadowMap?1.2:.08,1,1,3),meadowMaterial,count),p=new T.Object3D();grass.userData.kind='harvestable-hay-grass';grass.userData.area=F.w*F.d;grass.receiveShadow=true;grass.castShadow=false;
 for(let i=0;i<count;i++){const j=Math.floor(i/2),x=F.x+Math.sin(j*127.1)*F.w*.48,z=F.z+Math.sin(j*311.7+.3)*F.d*.48,h=.65+(j%11)*.035;p.position.set(x,height(x,z)+h/2-.03,z);p.rotation.set(0,j*2.4+(i%2)*Math.PI/2,0);p.scale.set(.7+(j%7)*.07,h,1);p.updateMatrix();grass.setMatrixAt(i,p.matrix);}root.add(grass);animated.push(t=>clock.value=t);
 const bale=new T.Group();bale.position.set(F.entry.x-.3,height(F.entry.x,F.entry.z),F.entry.z-1.1);root.add(bale);bale.userData.kind='harvested-hay-bale';const roll=mesh(new T.CylinderGeometry(.5,.5,1.05,24),hayMat,bale);roll.rotation.z=Math.PI/2;roll.position.y=.51;for(const x of[-.35,.35]){const tie=mesh(new T.TorusGeometry(.505,.015,6,32),wood,bale);tie.rotation.y=Math.PI/2;tie.position.set(x,.51,0);}const bales=[bale];for(let i=1;i<4;i++){const b=bale.clone();b.position.x+=i*.9;b.position.y=height(b.position.x,b.position.z);root.add(b);bales.push(b);}interactive.push({id:'hay-field',name:'Heuwiese mähen & Heu einsammeln',...F.entry,range:2.6,hayField:true});
 const dog=new T.Group();scene.add(dog);dog.userData.kind='border-collie-companion';ball(dog,black,0,.57,0,.2,.26,.47);ball(dog,white,0,.65,.3,.23,.28,.2);ball(dog,black,0,.88,.4,.18,.2,.22);ball(dog,white,0,.92,.56,.055,.13,.12);ball(dog,white,0,.78,.65,.12,.08,.15);ball(dog,black,0,.8,.78,.06,.04,.04);for(const side of[-1,1]){const ear=mesh(new T.ConeGeometry(.095,.23,10),black,dog);ear.position.set(side*.15,1.09,.37);ear.rotation.z=side*.24;ball(dog,black,side*.135,.91,.565,.023,.023,.02);ball(dog,white,side*.14,.918,.58,.006,.006,.007);}
 const legs=[];for(const x of[-.14,.14])for(const z of[-.3,.3]){const pivot=new T.Group();pivot.position.set(x,.52,z);dog.add(pivot);rod(pivot,[0,0,0],[0,-.4,.03],.045,white);ball(pivot,white,0,-.43,.08,.06,.045,.1);legs.push(pivot);}const tail=rod(dog,[0,.62,-.4],[0,.47,-.85],.07,black);ball(dog,white,0,.47,-.85,.07,.07,.13);
 let dogPath=[],replan=0,active=false;function dogStep(player,dt,visible){dog.visible=visible;if(!visible){active=false;return;}replan-=dt;const d=Math.hypot(dog.position.x-player.x,dog.position.z-player.z);if(!active||d>35){const candidates=Array.from({length:16},(_,i)=>({x:player.x+Math.cos(i*2.4)*1.8,z:player.z+Math.sin(i*2.4)*1.8})),q=candidates.find(q=>!blocked(q.x,q.z,colliders,.22));if(q){dog.position.set(q.x,height(q.x,q.z),q.z);active=true;}else return;dogPath=[];}
 if(d>2.3&&replan<=0){dogPath=route({x:dog.position.x,z:dog.position.z},player,colliders);replan=.8;}let moving=false;if(d>1.6&&dogPath.length){const q=dogPath[0],dx=q.x-dog.position.x,dz=q.z-dog.position.z,len=Math.hypot(dx,dz),step=Math.min(len,dt*4.1);if(len<.05)dogPath.shift();else{const x=dog.position.x+dx/len*step,z=dog.position.z+dz/len*step;if(!blocked(x,z,colliders,.22)){dog.position.set(x,height(x,z),z);dog.rotation.y=Math.atan2(dx,dz);moving=true;}else{dogPath=[];replan=0;}}}const t=performance.now()/1000;legs.forEach((l,i)=>l.rotation.x=moving?Math.sin(t*12+i*Math.PI)*.42:0);tail.rotation.z=Math.sin(t*5)*.13;}
 // Two sheep in the sheltered livestock pasture, with a continuous wool silhouette.
 for(let i=0;i<2;i++){const g=new T.Group();scene.add(g);g.userData.kind='alpine-sheep';const x=26.8,z=5.1-i*1.1;g.position.set(x,height(x,z),z);g.scale.setScalar(.8);ball(g,wool,0,.78,0,.35,.36,.57);for(let j=0;j<28;j++){const a=j*2.4;ball(g,wool,Math.cos(a)*.3,.79+Math.sin(j*1.7)*.22,Math.sin(a)*.49,.14,.13,.14);}ball(g,tan,0,.94,.59,.14,.21,.22);for(const side of[-1,1]){ball(g,tan,side*.22,1,.52,.14,.045,.07);ball(g,black,side*.13,.99,.71,.02,.025,.02);for(const zz of[-.34,.34])rod(g,[side*.23,.65,zz],[side*.23,.07,zz],.045,tan);}animated.push(t=>{const housed=lifeState?.alpLife.housed.goats,px=housed?2.8+i*.8:x,pz=housed?-10.2:z;g.position.set(px,height(px,pz),pz);g.rotation.y=.3+Math.sin(t*.13+i)*.16;});}
 return{grass,dog,dogStep,sync(s){lifeState=s;grass.visible=s.alpLife.hayCutDay!==s.day;bales.forEach((b,i)=>b.visible=s.alpLife.hayCutDay===s.day&&s.alpLife.hayCollected<(i+1)*8);}};
}
